pub fn largest_power_of_two_le(n: i8) -> i8 {
    debug_assert!(n >= 1);

    let mut z: i8 = 1;
    // Maintain: z is a power of two and 1 <= z <= n.
    // Doubling stops once the next power would exceed n.
    while z <= n / 2 {
        z *= 2;
    }
    z
}

pub fn solve(n: i8) -> i8 {
    debug_assert!(n >= 1);

    if n % 2 != 0 {
        (n - 1) / 2
    } else {
        let z = largest_power_of_two_le(n);
        (n - z) / 2
    }
}